import type { CartLine } from '#shared/types/cart'

export interface Quote {
  subtotal: string
  discount: string
  total: string
}

export interface QuoteCents {
  subtotal: number
  discount: number
  total: number
}

/** Prices the lines in cents, the single source of truth for both quotes and orders. */
export function computeQuoteCents(lines: CartLine[], code?: string): QuoteCents {
  const subtotal = sumBy(lines, line => (findProduct(line.slug)?.priceCents ?? 0) * line.qty)
  const discount = computeDiscount(subtotal, discountPercent(code))
  return { subtotal, discount, total: subtotal - discount }
}

export function computeQuote(lines: CartLine[], code?: string): Quote {
  const cents = computeQuoteCents(lines, code)
  return {
    subtotal: formatMoney(cents.subtotal),
    discount: formatMoney(cents.discount),
    total: formatMoney(cents.total),
  }
}

export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** A stored order. Amounts are what the server charged. */
export interface Order {
  id: string
  lines: OrderLine[]
  subtotal: string
  discount: string
  total: string
  totalCents: number
}

